// ==UserScript==
// @author       Journey Over
// @exclude      *
// ==UserLibrary==
// @name         @journeyover/mydublist
// @description  MyDubList client for checking multilingual anime dub availability
// @license      MIT
// @version      2.0.0
// @homepageURL  https://github.com/StylusThemes/Userscripts
// ==/UserLibrary==
// @connect      raw.githubusercontent.com
// @grant        GM_xmlhttpRequest
// ==/UserScript==

this.MyDubList=class{static LANGUAGES=Object.freeze([{name:'Arabic',value:'ARABIC'},{name:'Catalan',value:'CATALAN'},{name:'Chinese',value:'CHINESE'},{name:'Danish',value:'DANISH'},{name:'Dutch',value:'DUTCH'},{name:'English',value:'ENGLISH'},{name:'Finnish',value:'FINNISH'},{name:'French',value:'FRENCH'},{name:'German',value:'GERMAN'},{name:'Hebrew',value:'HEBREW'},{name:'Hindi',value:'HINDI'},{name:'Hungarian',value:'HUNGARIAN'},{name:'Indonesian',value:'INDONESIAN'},{name:'Italian',value:'ITALIAN'},{name:'Japanese',value:'JAPANESE'},{name:'Korean',value:'KOREAN'},{name:'Lithuanian',value:'LITHUANIAN'},{name:'Norwegian',value:'NORWEGIAN'},{name:'Polish',value:'POLISH'},{name:'Portuguese',value:'PORTUGUESE'},{name:'Russian',value:'RUSSIAN'},{name:'Spanish',value:'SPANISH'},{name:'Swedish',value:'SWEDISH'},{name:'Filipino',value:'FILIPINO',file:'tagalog'},{name:'Thai',value:'THAI'},{name:'Turkish',value:'TURKISH'},{name:'Vietnamese',value:'VIETNAMESE'}]);static CONFIDENCES=Object.freeze([{name:'Low',value:'low'},{name:'Normal',value:'normal'},{name:'High',value:'high'},{name:'Very High',value:'very-high'}]);static DEFAULT_LANGUAGE='english';static DEFAULT_CONFIDENCE='normal';static TIMEOUT_MS=15e3;constructor(){this._baseUrl='https://raw.githubusercontent.com/Joelis57/MyDubList/main/dubs/confidence';this._cache=new Map;this._pending=new Map;this._generation=0}static _slug(value){return String(value??'').trim().toLowerCase().replace(/[\s_]+/g,'-')}_findLanguage(language){const slug=this.constructor._slug(language);return this.constructor.LANGUAGES.find(entry=>slug===entry.value.toLowerCase()||slug===entry.file)}_resolveLanguage(language=this.constructor.DEFAULT_LANGUAGE){const entry=this._findLanguage(language);if(entry)return entry.file??entry.value.toLowerCase();const slug=this.constructor._slug(language);if(!/^[a-z][a-z-]*$/.test(slug)){throw new Error(`Unsupported MyDubList language: ${language}`)}return slug}_resolveConfidence(confidence=this.constructor.DEFAULT_CONFIDENCE){const slug=this.constructor._slug(confidence).replace(/^veryhigh$/,'very-high');if(!this.constructor.CONFIDENCES.some(entry=>entry.value===slug)){throw new Error(`Unsupported MyDubList confidence: ${confidence}`)}return slug}_normalizeMalId(id){const normalized=Number(id);if(!Number.isInteger(normalized)||normalized<=0){throw new Error(`Invalid MyAnimeList ID: ${id}`)}return normalized}_get(url){return new Promise((resolve,reject)=>{GM_xmlhttpRequest({method:'GET',url:url,timeout:this.constructor.TIMEOUT_MS,onload:response=>{if(response.status!==200){reject(new Error(`MyDubList request failed with status ${response.status}`));return}resolve(response.responseText)},onerror:()=>reject(new Error('An error occurs while processing the MyDubList request')),ontimeout:()=>reject(new Error('MyDubList request times out'))})})}_parse(text){let payload;try{payload=JSON.parse(text)}catch{throw new Error('Failed to parse MyDubList response')}if(!Array.isArray(payload?.dubbed)){throw new Error('Unexpected MyDubList response structure')}return{dubbed:new Set(payload.dubbed.map(Number))}}_load(language,confidence){const resolvedLanguage=this._resolveLanguage(language);const resolvedConfidence=this._resolveConfidence(confidence);const key=`${resolvedLanguage}:${resolvedConfidence}`;const existing=this._cache.get(key)??this._pending.get(key);if(existing)return Promise.resolve(existing);const generation=this._generation;const request=this._get(`${this._baseUrl}/${resolvedConfidence}/dubbed_${resolvedLanguage}.json`).then(text=>this._parse(text)).then(entry=>{if(generation===this._generation)this._cache.set(key,entry);return entry}).finally(()=>{if(this._pending.get(key)===request)this._pending.delete(key)});this._pending.set(key,request);return request}async isDubbed(id,{language:language,confidence:confidence}={}){const malId=this._normalizeMalId(id);const{dubbed:dubbed}=await this._load(language,confidence);return dubbed.has(malId)}languageName(language){return this._findLanguage(language)?.name??'Dub'}formatDubLabel(language){return`${this.languageName(language)} Dub Exists`}clearCache(){this._generation++;this._cache.clear();this._pending.clear()}};
